import {chunkInView,modelViewMargin} from './chunk-view.js';
import { chunkKey } from './site.js';
import { buildMesh } from './mesh.js';
export class ChunkMesher{
 constructor(){this.site=null;this.resources=null;this.resourceVersion=-1;this.signature='';this.meta=new Map();this.dirty=new Set();this.sentTextures=new Set();this.visibility=[];this.visibilitySignature="";this.resident=new Set();this.deferred=new Set();}
 changed(site){for(const p of site.changedPositions){this.dirty.add(chunkKey(p));for(let a=0;a<3;a++)for(const d of[-1,1]){const n=[...p];n[a]+=d;if(n[a]>=0&&n[a]<4096)this.dirty.add(chunkKey(n));}}}
 render(site,resources,options={}){if(options.chunkBudget!==undefined&&(!Number.isInteger(options.chunkBudget)||options.chunkBudget<1||options.chunkBudget>4096))throw Error('Invalid mesh chunk budget');if(options.viewFocus!==undefined&&(!Array.isArray(options.viewFocus)||options.viewFocus.length!==3||options.viewFocus.some(n=>!Number.isFinite(n))))throw Error('Invalid mesh view focus');for(const key of options.releasedTextures||[])this.sentTextures.delete(key);const started=performance.now(),opts={...options,cut:options.cut>=site.size[1]-1?4095:options.cut},signature=JSON.stringify({...opts,hidden:undefined,animated:undefined,viewPlanes:undefined,releasedTextures:undefined,chunkBudget:undefined,viewFocus:undefined})+'|'+resources.version,resetTextures=this.resources!==resources||this.resourceVersion!==resources.version,reset=this.site!==site||resetTextures||this.signature!==signature;
  const visibility=[...(opts.hidden||[]),...(opts.animated||[])],visibilitySignature=JSON.stringify(visibility);if(visibilitySignature!==this.visibilitySignature&&!reset)for(const r of [...this.visibility,...visibility])for(let x=Math.floor(Math.max(0,r.min[0]-1)/16);x<=Math.floor((r.max[0]+1)/16);x++)for(let y=Math.floor(Math.max(0,r.min[1]-1)/16);y<=Math.floor((r.max[1]+1)/16);y++)for(let z=Math.floor(Math.max(0,r.min[2]-1)/16);z<=Math.floor((r.max[2]+1)/16);z++)this.dirty.add([x,y,z].join(','));this.visibility=visibility;this.visibilitySignature=visibilitySignature;
  if(reset||this.paletteSize!==site.palette.length||opts.viewPlanes&&!this.marginResolved){this.paletteSize=site.palette.length;this.viewMargin=opts.viewPlanes?Math.max(2,...site.palette.map(state=>modelViewMargin(resources.model(state)))):2;this.marginResolved=!!opts.viewPlanes;}const allKeys=new Set([...site.baseChunks.keys(),...site.overlayChunks.keys()]),wanted=new Set([...allKeys].filter(key=>chunkInView(key,opts.viewPlanes,this.viewMargin))),evicted=[...this.resident].filter(key=>!wanted.has(key));for(const key of evicted){this.resident.delete(key);this.meta.delete(key);}const keys=reset?new Set(wanted):new Set([...this.dirty,...this.deferred,...[...wanted].filter(k=>!this.resident.has(k))]);for(const key of [...keys])if(!wanted.has(key)){keys.delete(key);this.deferred.add(key);}if(reset){this.meta.clear();this.sentTextures.clear();this.resident.clear();this.deferred.clear();}let ordered=[...keys];if(opts.viewFocus){const distance=key=>key.split(',').reduce((n,v,a)=>n+(Number(v)*16+8-opts.viewFocus[a])**2,0);ordered.sort((a,b)=>distance(a)-distance(b)||a.localeCompare(b));}const pending=Math.max(0,ordered.length-(opts.chunkBudget||ordered.length));if(opts.chunkBudget){for(const key of ordered.slice(opts.chunkBudget))this.deferred.add(key);ordered=ordered.slice(0,opts.chunkBudget);}for(const key of ordered)this.deferred.delete(key);const chunks=[],textures={};let visited=0;
  for(const key of ordered){visited+=(site.baseChunks.get(key)?.size||0)+(site.overlayChunks.get(key)?.size||0);const result=buildMesh(site,resources,{...opts,chunk:key});chunks.push({key,buckets:result.buckets,triangles:result.triangles});this.resident.add(key);this.meta.set(key,{triangles:result.triangles,issues:result.issues});for(const b of result.buckets)if(b.texture&&!this.sentTextures.has(b.texture)){textures[b.texture]=resources.texture(b.texture);this.sentTextures.add(b.texture);}}
  this.site=site;this.resources=resources;this.resourceVersion=resources.version;this.signature=signature;this.dirty.clear();return{reset,resetTextures,chunks,evicted,textures,triangles:[...this.meta.values()].reduce((n,m)=>n+m.triangles,0),issues:[...new Set([...this.meta.values()].flatMap(m=>m.issues))],stats:{pending,chunks:chunks.length,resident:this.resident.size,total:allKeys.size,candidates:visited,meshMs:performance.now()-started,...(site.baseline?{source:site.baseline.stats()}:{})}};
 }
}
